  try {
    function getShadowText(root) {
      let results = [];
      let walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT, null, false);
      let node = walker.currentNode;
      while (node) {
        if (node.tagName && node.tagName.toLowerCase().includes('review')) {
          results.push(node.textContent.trim());
        }
        if (node.shadowRoot) {
          results = results.concat(getShadowText(node.shadowRoot));
        }
        node = walker.nextNode();
      }
      return results;
    }

    // Find all review cards or texts across shadow roots
    let allNodes = Array.from(document.querySelectorAll('*'));
