      // Alternative: search for json scripts or page components
      let managers = document.querySelectorAll('page-media-reviews-manager, media-reviews-manager, reviews-manager');
      managers.forEach(m => {
        if (m.getAttribute('reviews')) reviews.push(m.getAttribute('reviews'));
      });
    }

    return {
      count: reviews.length,
      reviews: reviews.slice(0, 15),
      bodyTextSnippet: document.body.innerText.substring(0, 1000)
    };
